61	export enum ToolCallStatus {
62	  Pending = 'Pending',
63	  Canceled = 'Canceled',
64	  Confirming = 'Confirming',
65	  Executing = 'Executing',
66	  Success = 'Success',
67	  Error = 'Error',
68	}
