70	/**
71	 * Maps core tool call status to a simplified UI status.
72	 */
73	export function mapCoreStatusToDisplayStatus(
74	  coreStatus: CoreToolCallStatus,
75	): ToolCallStatus {
76	  switch (coreStatus) {
77	    case CoreToolCallStatus.Validating:
78	      return ToolCallStatus.Pending;
79	    case CoreToolCallStatus.AwaitingApproval:
80	      return ToolCallStatus.Confirming;
81	    case CoreToolCallStatus.Executing:
82	      return ToolCallStatus.Executing;
83	    case CoreToolCallStatus.Success:
84	      return ToolCallStatus.Success;
85	    case CoreToolCallStatus.Cancelled:
86	      return ToolCallStatus.Canceled;
87	    case CoreToolCallStatus.Error:
88	      return ToolCallStatus.Error;
89	    case CoreToolCallStatus.Scheduled:
90	      return ToolCallStatus.Pending;
91	    default:
92	      return checkExhaustive(coreStatus);
93	  }
94	}
