16	export enum MessageBusType {
17	  TOOL_CONFIRMATION_REQUEST = 'tool-confirmation-request',
18	  TOOL_CONFIRMATION_RESPONSE = 'tool-confirmation-response',
19	  TOOL_POLICY_REJECTION = 'tool-policy-rejection',
20	  TOOL_EXECUTION_SUCCESS = 'tool-execution-success',
21	  TOOL_EXECUTION_FAILURE = 'tool-execution-failure',
22	  UPDATE_POLICY = 'update-policy',
23	  TOOL_CALLS_UPDATE = 'tool-calls-update',
24	  ASK_USER_REQUEST = 'ask-user-request',
25	  ASK_USER_RESPONSE = 'ask-user-response',
26	}
27	
28	export interface ToolCallsUpdateMessage {
29	  type: MessageBusType.TOOL_CALLS_UPDATE;
30	  toolCalls: ToolCall[];
31	  schedulerId: string;
32	}
33	
34	export interface ToolConfirmationRequest {
35	  type: MessageBusType.TOOL_CONFIRMATION_REQUEST;
36	  toolCall: FunctionCall;
37	  correlationId: string;
38	  serverName?: string;
39	  /**
40	   * Optional tool annotations (e.g., readOnlyHint, destructiveHint) from MCP.
41	   */
42	  toolAnnotations?: Record<string, unknown>;
43	  /**
44	   * Optional subagent name, if this tool call was initiated by a subagent.
45	   */
46	  subagent?: string;
47	  /**
48	   * Optional rich details for the confirmation UI (diffs, counts, etc.)
49	   */
50	  details?: SerializableConfirmationDetails;
51	  /**
52	   * Optional decision to force for this tool call, bypassing the policy engine.
53	   */
54	  forcedDecision?: 'allow' | 'deny' | 'ask_user';
55	}
56	
57	export interface ToolConfirmationResponse {
58	  type: MessageBusType.TOOL_CONFIRMATION_RESPONSE;
59	  correlationId: string;
60	  confirmed: boolean;
61	  /**
62	   * The specific outcome selected by the user.
63	   *
64	   * TODO: Make required after migration.
65	   */
66	  outcome?: ToolConfirmationOutcome;
67	  /**
68	   * Optional payload (e.g., modified content for 'modify_with_editor').
69	   */
70	  payload?: ToolConfirmationPayload;
71	  /**
72	   * When true, indicates that policy decision was ASK_USER and the tool should
73	   * show its legacy confirmation UI instead of auto-proceeding.
74	   */
75	  requiresUserConfirmation?: boolean;
76	}
77	
78	/**
79	 * Data-only versions of ToolCallConfirmationDetails for bus transmission.
80	 */
81	export type SerializableConfirmationDetails =
82	  | {
83	      type: 'sandbox_expansion';
84	      title: string;
85	      command: string;
86	      rootCommand: string;
87	      additionalPermissions: SandboxPermissions;
88	      systemMessage?: string;
89	    }
90	  | {
91	      type: 'info';
92	      title: string;
93	      systemMessage?: string;
94	      prompt: string;
95	      urls?: string[];
96	    }
97	  | {
98	      type: 'edit';
99	      title: string;
100	      systemMessage?: string;
101	      fileName: string;
102	      filePath: string;
103	      fileDiff: string;
104	      originalContent: string | null;
105	      newContent: string;
106	      isModifying?: boolean;
107	      diffStat?: DiffStat;
108	    }
109	  | {
110	      type: 'exec';
111	      title: string;
112	      systemMessage?: string;
113	      command: string;
114	      rootCommand: string;
115	      rootCommands: string[];
116	      commands?: string[];
117	    }
118	  | {
119	      type: 'mcp';
120	      title: string;
121	      systemMessage?: string;
122	      serverName: string;
123	      toolName: string;
124	      toolDisplayName: string;
125	      toolArgs?: Record<string, unknown>;
126	      toolDescription?: string;
127	      toolParameterSchema?: unknown;
128	    }
129	  | {
130	      type: 'ask_user';
131	      title: string;
132	      systemMessage?: string;
133	      questions: Question[];
134	    }
135	  | {
136	      type: 'exit_plan_mode';
137	      title: string;
138	      systemMessage?: string;
139	      planPath: string;
140	    };
141	
142	export interface UpdatePolicy {
143	  type: MessageBusType.UPDATE_POLICY;
144	  toolName: string;
145	  persist?: boolean;
146	  persistScope?: 'workspace' | 'user';
147	  argsPattern?: string;
148	  commandPrefix?: string | string[];
149	  mcpName?: string;
150	  allowRedirection?: boolean;
151	}
152	
153	export interface ToolPolicyRejection {
154	  type: MessageBusType.TOOL_POLICY_REJECTION;
155	  toolCall: FunctionCall;
156	}
157	
158	export interface ToolExecutionSuccess<T = unknown> {
159	  type: MessageBusType.TOOL_EXECUTION_SUCCESS;
160	  toolCall: FunctionCall;
161	  result: T;
162	}
163	
164	export interface ToolExecutionFailure<E = Error> {
165	  type: MessageBusType.TOOL_EXECUTION_FAILURE;
166	  toolCall: FunctionCall;
167	  error: E;
168	}
169	
170	export interface QuestionOption {
171	  label: string;
172	  description: string;
173	}
174	
175	export enum QuestionType {
176	  CHOICE = 'choice',
177	  TEXT = 'text',
178	  YESNO = 'yesno',
179	}
180	
181	export interface Question {
182	  question: string;
183	  header: string;
184	  /** Question type: 'choice' renders selectable options, 'text' renders free-form input, 'yesno' renders a binary Yes/No choice. */
185	  type: QuestionType;
186	  /** Selectable choices. REQUIRED when type='choice'. IGNORED for 'text' and 'yesno'. */
187	  options?: QuestionOption[];
188	  /** Allow multiple selections. Only applies when type='choice'. */
189	  multiSelect?: boolean;
190	  /** Placeholder hint text. For type='text', shown in the input field. For type='choice', shown in the "Other" custom input. */
191	  placeholder?: string;
192	  /** Allow the question to consume more vertical space instead of being strictly capped. */
193	  unconstrainedHeight?: boolean;
194	}
195	
196	export interface AskUserRequest {
197	  type: MessageBusType.ASK_USER_REQUEST;
198	  questions: Question[];
199	  correlationId: string;
200	}
201	
202	export interface AskUserResponse {
203	  type: MessageBusType.ASK_USER_RESPONSE;
204	  correlationId: string;
205	  answers: { [questionIndex: string]: string };
206	  /** When true, indicates the user cancelled the dialog without submitting answers */
207	  cancelled?: boolean;
208	}
209	
210	export type Message =
211	  | ToolConfirmationRequest
212	  | ToolConfirmationResponse
213	  | ToolPolicyRejection
214	  | ToolExecutionSuccess
215	  | ToolExecutionFailure
216	  | UpdatePolicy
217	  | AskUserRequest
218	  | AskUserResponse
219	  | ToolCallsUpdateMessage;
