7	import { randomUUID } from 'node:crypto';
8	import { EventEmitter } from 'node:events';
9	import type { PolicyEngine } from '../policy/policy-engine.js';
10	import { PolicyDecision } from '../policy/types.js';
11	import { MessageBusType, type Message } from './types.js';
12	import { safeJsonStringify } from '../utils/safeJsonStringify.js';
13	import { debugLogger } from '../utils/debugLogger.js';
14	
15	export class MessageBus extends EventEmitter {
16	  constructor(
17	    private readonly policyEngine: PolicyEngine,
18	    private readonly debug = false,
19	  ) {
20	    super();
21	    this.debug = debug;
22	  }
23	
24	  private isValidMessage(message: Message): boolean {
25	    if (!message || !message.type) {
26	      return false;
27	    }
28	
29	    if (
30	      message.type === MessageBusType.TOOL_CONFIRMATION_REQUEST &&
31	      !('correlationId' in message)
32	    ) {
33	      return false;
34	    }
35	
36	    return true;
37	  }
38	
39	  private emitMessage(message: Message): void {
40	    this.emit(message.type, message);
41	  }
42	
43	  /**
44	   * Derives a child message bus scoped to a specific subagent.
45	   */
46	  derive(subagentName: string): MessageBus {
47	    const bus = new MessageBus(this.policyEngine, this.debug);
48	
49	    bus.publish = async (message: Message) => {
50	      if (message.type === MessageBusType.TOOL_CONFIRMATION_REQUEST) {
51	        return this.publish({
52	          ...message,
53	          subagent: message.subagent
54	            ? `${subagentName}/${message.subagent}`
55	            : subagentName,
56	        });
57	      }
58	      return this.publish(message);
59	    };
60	
61	    // Delegate subscription methods to the parent bus
62	    bus.subscribe = this.subscribe.bind(this);
63	    bus.unsubscribe = this.unsubscribe.bind(this);
64	    bus.on = this.on.bind(this);
65	    bus.off = this.off.bind(this);
66	    bus.emit = this.emit.bind(this);
67	    bus.once = this.once.bind(this);
68	    bus.removeListener = this.removeListener.bind(this);
69	    bus.listenerCount = this.listenerCount.bind(this);
70	
71	    return bus;
72	  }
73	
74	  async publish(message: Message): Promise<void> {
75	    if (this.debug) {
76	      debugLogger.debug(`[MESSAGE_BUS] publish: ${safeJsonStringify(message)}`);
77	    }
78	    try {
79	      if (!this.isValidMessage(message)) {
80	        throw new Error(
81	          `Invalid message structure: ${safeJsonStringify(message)}`,
82	        );
83	      }
84	
85	      if (message.type === MessageBusType.TOOL_CONFIRMATION_REQUEST) {
86	        const { decision: policyDecision } = await this.policyEngine.check(
87	          message.toolCall,
88	          message.serverName,
89	          message.toolAnnotations,
90	          message.subagent,
91	        );
92	
93	        const decision = message.forcedDecision ?? policyDecision;
94	
95	        switch (decision) {
96	          case PolicyDecision.ALLOW:
97	            // Directly emit the response instead of recursive publish
98	            this.emitMessage({
99	              type: MessageBusType.TOOL_CONFIRMATION_RESPONSE,
100	              correlationId: message.correlationId,
101	              confirmed: true,
102	            });
103	            break;
104	          case PolicyDecision.DENY:
105	            // Emit both rejection and response messages
106	            this.emitMessage({
107	              type: MessageBusType.TOOL_POLICY_REJECTION,
108	              toolCall: message.toolCall,
109	            });
110	            this.emitMessage({
111	              type: MessageBusType.TOOL_CONFIRMATION_RESPONSE,
112	              correlationId: message.correlationId,
113	              confirmed: false,
114	            });
115	            break;
116	          case PolicyDecision.ASK_USER:
117	            // Pass through to UI for user confirmation if any listeners exist.
118	            // If no listeners are registered (e.g., headless/ACP flows),
119	            // immediately request user confirmation to avoid long timeouts.
120	            if (
121	              this.listenerCount(MessageBusType.TOOL_CONFIRMATION_REQUEST) > 0
122	            ) {
123	              this.emitMessage(message);
124	            } else {
125	              this.emitMessage({
126	                type: MessageBusType.TOOL_CONFIRMATION_RESPONSE,
127	                correlationId: message.correlationId,
128	                confirmed: false,
129	                requiresUserConfirmation: true,
130	              });
131	            }
132	            break;
133	          default:
134	            throw new Error(`Unknown policy decision: ${decision}`);
135	        }
136	      } else {
137	        // For all other message types, just emit them
138	        this.emitMessage(message);
139	      }
140	    } catch (error) {
141	      this.emit('error', error);
142	    }
143	  }
144	
145	  subscribe<T extends Message>(
146	    type: T['type'],
147	    listener: (message: T) => void,
148	  ): void {
149	    this.on(type, listener);
150	  }
151	
152	  unsubscribe<T extends Message>(
153	    type: T['type'],
154	    listener: (message: T) => void,
155	  ): void {
156	    this.off(type, listener);
157	  }
158	
159	  /**
160	   * Request-response pattern: Publish a message and wait for a correlated response
161	   * This enables synchronous-style communication over the async MessageBus
162	   * The correlation ID is generated internally and added to the request
163	   */
164	  async request<TRequest extends Message, TResponse extends Message>(
165	    request: Omit<TRequest, 'correlationId'>,
166	    responseType: TResponse['type'],
167	    timeoutMs: number = 60000,
168	  ): Promise<TResponse> {
169	    const correlationId = randomUUID();
170	
171	    return new Promise<TResponse>((resolve, reject) => {
172	      const timeoutId = setTimeout(() => {
173	        cleanup();
174	        reject(new Error(`Request timed out waiting for ${responseType}`));
175	      }, timeoutMs);
176	
177	      const cleanup = () => {
178	        clearTimeout(timeoutId);
179	        this.unsubscribe(responseType, responseHandler);
180	      };
181	
182	      const responseHandler = (response: TResponse) => {
183	        // Check if this response matches our request
184	        if (
185	          'correlationId' in response &&
186	          response.correlationId === correlationId
187	        ) {
188	          cleanup();
189	          resolve(response);
190	        }
191	      };
192	
193	      // Subscribe to responses
194	      this.subscribe<TResponse>(responseType, responseHandler);
195	
196	      // Publish the request with correlation ID
197	      // eslint-disable-next-line @typescript-eslint/no-floating-promises, @typescript-eslint/no-unsafe-type-assertion
198	      this.publish({ ...request, correlationId } as TRequest);
199	    });
200	  }
201	}
