      type: 'mcp';
      title: string;
      systemMessage?: string;
      serverName: string;
      toolName: string;
      toolDisplayName: string;
      toolArgs?: Record<string, unknown>;
      toolDescription?: string;
      toolParameterSchema?: unknown;
    }
  | {
      type: 'ask_user';
      title: string;
      systemMessage?: string;
      questions: Question[];
    }
  | {
      type: 'exit_plan_mode';
      title: string;
      systemMessage?: string;
      planPath: string;
    };

